  const uint k = 1103515245U;
vec3 hash33( uvec3 x )
{
    x = ((x>>8U)^x.yzx)*k;
    x = ((x>>8U)^x.yzx)*k;
    x = ((x>>8U)^x.yzx)*k;

    return vec3(x)*(1.0/float(0xffffffffU));
}//Taken from one of IQ's shaders

#define ITERATIONS 5
#define USE_DITHER 1

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    uvec3 p = uvec3(fragCoord, iFrame);

    vec2 uv = fragCoord/iResolution.xy;

    float X = length(uv-.5);
    vec2 dir = normalize(uv-.5) / iResolution.x;

    float noise = hash33(p).x;

    vec3 col = vec3(0.);
    float s = -100.;
    float demoStep = step(iMouse.x/iResolution.x, uv.x);

    for(int i = 0; i<ITERATIONS; i++)
    {
        vec2 UV = uv + dir * float(i) * s / float(ITERATIONS);


        UV += noise * dir / float(ITERATIONS) * s * demoStep;

        col += texture(iChannel0, UV).rgb;
    }      

    col /= float(ITERATIONS);


    // Output to screen
    fragColor = vec4(col,1.0);
}
